      val r7 = compute_case_CASE_ARB_03_PRIORITY(api_airProposal, api_humidityProposal, api_recoveryGate, api_requestIntent, api_airCareSupervisorStatus, api_airTreatmentCommand)
      val r8 = compute_case_CASE_ARB_03_FILTER_HUMIDITY_INVALID(api_airProposal, api_humidityProposal, api_recoveryGate, api_requestIntent, api_airCareSupervisorStatus, api_airTreatmentCommand)
      val r9 = compute_case_CASE_ARB_03_FILTER_DRYER_UNAVAILABLE(api_airProposal, api_humidityProposal, api_recoveryGate, api_requestIntent, api_airCareSupervisorStatus, api_airTreatmentCommand)
      val r10 = compute_case_CASE_ARB_04_DRYING(api_airProposal, api_humidityProposal, api_recoveryGate, api_requestIntent, api_airCareSupervisorStatus, api_airTreatmentCommand)
      val r11 = compute_case_CASE_ARB_04_AIR_INVALID(api_airProposal, api_humidityProposal, api_recoveryGate, api_requestIntent, api_airCareSupervisorStatus, api_airTreatmentCommand)
      val r12 = compute_case_CASE_ARB_04_FILTER_UNAVAILABLE(api_airProposal, api_humidityProposal, api_recoveryGate, api_requestIntent, api_airCareSupervisorStatus, api_airTreatmentCommand)
